Lemma u32le_range : forall c0 c1 c2 c3, 0 <= c0 < 256 -> 0 <= c1 < 256 -> 0 <= c2 < 256 -> 0 <= c3 < 256 ->
  0 <= u32le c0 c1 c2 c3 < 2^32.
Proof. intros. rewrite u32le_sum by lia. lia. Qed.

