Section HCW.
  Context {HCEIL : HeapCeil}.

(* [comment removed for export] *)

Ltac win_loadH WIN q :=
  lazymatch type of WIN with bytes_at _ ?mx ?it0 ?bs =>
    let b := fresh "b" in let N := fresh "N" in let RD := fresh "RD" in let BR := fresh "BR" in
    destruct (win_byte _ _ _ q WIN ltac:(lia)) as [b N];
    pose proof (zb_range b) as BR; unfold zb in BR;
    pose proof (u8ro_read usegs _ it0 bs (q - it0) b (Z_to_bv 64 q) WIN N ltac:(lia) ltac:(symmetry; apply wa_of_Z_to_bv; lia)) as RD;
    step; clear RD; change (zxb b) with (Z_to_bv 64 (zb b)); fold (zb b) in BR
  end.
(* [comment removed for export] *)
Ltac win_loadN WIN N q :=
  lazymatch type of WIN with bytes_at _ ?mx ?it0 ?bs =>
  lazymatch type of N with nth_error _ _ = Some ?b =>
    let RD := fresh "RD" in let BR := fresh "BR" in
    pose proof (u8ro_read usegs _ it0 bs (q - it0) b (Z_to_bv 64 q) WIN ltac:(rewrite <- N; f_equal; lia) ltac:(lia) ltac:(symmetry; apply wa_of_Z_to_bv; lia)) as RD;
    step; clear RD; change (zxb b) with (Z_to_bv 64 (zb b)); try (pose proof (zb_range b) as BR; unfold zb in BR; fold (zb b) in BR)
  end end.

Definition getchars_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P : Z) (bs : list byte) (b0 b1 b2 b3 : byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 (gcw (zb b0) (zb b1) (zb b2) (zb b3))) a1 a2 a3 a4 a5 a6 a7
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch [] m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ bytes_at usegs m' P bs.

(* [comment removed for export] *)
Definition getchars_stmt : Prop :=
  forall (P : Z) (bs : list byte) (j : nat) (b0 b1 b2 b3 : byte)
    ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  bytes_at usegs m P bs -> P + Z.of_nat (length bs) < 2^64 -> 0 < P ->
  nth_error bs j = Some b0 -> nth_error bs (S j) = Some b1 -> nth_error bs (S (S j)) = Some b2 -> nth_error bs (S (S (S j))) = Some b3 ->
