Definition DIG_STACK : Z := 64.

Definition dig_post_v (v : Z) (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P lo : Z) (bs : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 (bv_swrap 32 v)) a1 a2 a3 a4 a5 a6 a7
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp)
    /\ bytes_at usegs m' P bs.

(* [comment removed for export] *)
Definition dig_ctx (m0 m : mem) (sp : word) (lo : Z) (rav s0v s1v s2v s3v s4v s5v s6v : word) (P : Z) (bs : list byte) : Prop :=
  rw_cells usegs m (bv_unsigned sp + -64) [C8 s6v; C8 s5v; C8 s4v; C8 s3v; C8 s2v; C8 s1v; C8 s0v; C8 rav]
  /\ bytes_at usegs m P bs
  /\ stk usegs m lo (bv_unsigned sp + -64)
  /\ munch [(lo, bv_unsigned sp)]%Z m0 m /\ wmono usegs m0 m /\ mem_inv usegs m.

Lemma dig1_acc : forall r c, 0 <= r < 2^32 -> 0 <= c < 256 ->
  Z_to_bv 64 (bv_swrap 32 (bv_unsigned (Z_to_bv 64 (Z.shiftl (bv_unsigned (Z_to_bv 64 (bv_swrap 32 r))) 2 + bv_swrap 32 r))
                           + bv_unsigned (Z_to_bv 64 (Z.lor (bv_unsigned (Z_to_bv 64 c)) 32))))
  = Z_to_bv 64 (bv_swrap 32 ((5 * r + Z.lor c 32) mod 2^32)).
