Lemma skipn_at_nth : forall {X} (l : list X) j x, nth_error l j = Some x -> skipn j l = x :: skipn (S j) l.
Proof.
  intros X l. induction l as [|y l IH]; intros [|j] x H; cbn in H |- *; try discriminate.
  - inversion H. reflexivity.
  - destruct l as [|z l']; [destruct j; discriminate|]. exact (IH j x H).
Qed.
Scheme kc__3 := Elimination for Corelib.Init.Logic.ex Sort Prop.

(* [comment removed for export] *)
Lemma dig_loop2 : forall k j rax sp gp tp t0 t1 t2 a2 a3 a4 a5 a6 a7 s4x s5x s6x s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m0 m : mem) (P lo : Z) (bs : list byte) (r : Z) (rav s0v s1v s2v s3v s4v s5v s6v : word),
  (length bs - j = k)%nat -> (j < length bs)%nat -> 0 <= r < 2^32 ->
  dig_ctx m0 m sp lo rav s0v s1v s2v s3v s4v s5v s6v P bs ->
  P + Z.of_nat (length bs) < 2^64 -> 0 < P -> lo + 64 <= bv_unsigned sp ->
  evt usegs (dig_post_v (ft_dig1 r (zbytes (skipn j bs))) rav sp gp tp s0v s1v s2v s3v s4v s5v s6v s7 s8 s9 s10 s11 F fc P lo bs m0)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -64)) gp tp t0 t1 t2 (wz (Z.of_nat (length bs) - Z.of_nat j)) (Z_to_bv 64 (bv_swrap 32 r))
              (Z_to_bv 64 18446744073709551615) (wz (P + Z.of_nat j)) a2 a3 a4 a5 a6 a7
              (wz (P + Z.of_nat j)) (wz 4) s4x s5x s6x s7 s8 s9 s10 s11 t3 t4 t5 t6)
