Lemma ft_digest_from_step4 : forall r x0 x1 x2 x3 rest,
  ft_digest_from r (x0 :: x1 :: x2 :: x3 :: rest) = ft_digest_from ((5 * r + Z.lor (u32le x0 x1 x2 x3) 0x20202020) mod 2^32) rest.
Proof. intros. reflexivity. Qed.
Lemma ft_digest_from_short : forall r rest, (length rest < 4)%nat -> ft_digest_from r rest = ft_dig1 r rest.
